mapper.select:
SELECT s.* FROM subject s

    JOIN subject_tag st ON s.id = st.subject_id AND st.name IN

        #{tag}




        AND (s.name LIKE CONCAT('%', #{keyword}, '%')
             OR s.name_cn LIKE CONCAT('%', #{keyword}, '%'))


        AND s.score >= #{scoreMin}


        AND s.score <= #{scoreMax}


        AND s.air_date >= CONCAT(#{year}, '-01-01')
        AND s.air_date <= CONCAT(#{year}, '-12-31')


        AND s.air_weekday = #{weekday}



    GROUP BY s.id
    HAVING COUNT(DISTINCT st.name) = ${tagList.size}

ORDER BY

    IF(s.name_cn LIKE CONCAT('%', #{keyword}, '%'), 0, 1),

${sortField} ${order}
